entries[276345] = { ["name"] = "Malfunctioning Holoprint", ["text"] = "\"The holoprint is quite unreadable as warped projections and random rune flicker across the screen.\"\nSell Price:" }
entries[276346] = { ["name"] = "Fel-Singed Salvage", ["text"] = "\"A twisted metal scrap once belonging to some part of a Legion vessel.\"\nSell Price:" }
entries[276347] = { ["name"] = "Cracked Legion Communicator", ["text"] = "\"For a moment you're sure you can hear a voice emitting from the defunct device.\"\nSell Price:" }
entries[276348] = { ["name"] = "Marsh Wrangler's Vinewhip", ["text"] = "\"Strange alien letters are carved into the base of the whip.\"\nSell Price:" }
entries[276349] = { ["name"] = "Bulbous Leyshroom", ["text"] = "\"The bulb-like mushroom glows with a faint arcane light.\"\nSell Price:" }
entries[276350] = { ["name"] = "Shimmering Algae", ["text"] = "\"Tiny flecks of energy cling to the algae.\"\nSell Price:" }
entries[276351] = { ["name"] = "Muckfaded Crystalline Figure", ["text"] = "\"The details and etchings once carved into the figure have been eroded away by the swamp mud.\"\nSell Price:" }
entries[276352] = { ["name"] = "Scuffed Prayer Bangle", ["text"] = "\"The prayer runes carved into the bracelet have been eroded away by years of swamp water.\"\nSell Price:" }
entries[276353] = { ["name"] = "Frozen Sliver of Darkness", ["text"] = "\"A single sliver of pure Void energy appears to be imprisoned within the ice.\"\nSell Price:" }
entries[276354] = { ["name"] = "Frozen Fel Core", ["text"] = "\"Once used to power the Legion's war machines, the core is now cold and lifeless.\"\nSell Price:" }
entries[276355] = { ["name"] = "Shattered Frostforged Hilt", ["text"] = "\"Forged, honed, and shattered in the frozen valleys of Val long ago.\"\nSell Price:" }
entries[276356] = { ["name"] = "Frost-Shredded Demon Cloak", ["text"] = "\"This cloak did little to protect its owner from the ice storms of Val.\"\nSell Price:" }
entries[276357] = { ["name"] = "Razor-Ice Flake", ["text"] = "\"\"If the cold winds don't kill you, the dagger-sized ice flakes will.\" - A Demon's Guide to Surviving Val.\"\nSell Price:" }
entries[276358] = { ["name"] = "Shattered Shadowgraft", ["text"] = "\"Once used to control and bend the mind of its wearer.\"\nSell Price:" }
entries[276359] = { ["name"] = "Twisted Domanaar Armament", ["text"] = "\"Lifeless and cold to the touch.\"\nSell Price:" }
entries[276360] = { ["name"] = "Etched Ice Chip", ["text"] = "\"Strange symbols have been etched deep into the ice.\"\nSell Price:" }
entries[276361] = { ["name"] = "Frost-Calloused Remains", ["text"] = "\"The unidentifiable frozen remains of... something that perished on Val.\"\nSell Price:" }
entries[276362] = { ["name"] = "Lost Glacier Climbing Hooks", ["text"] = "\"The glacial cave systems of Val are impossible to traverse without some stabilization.\"\nSell Price:" }
entries[276364] = { ["name"] = "Arsenal: Lightforged Armaments", ["text"] = "Binds to Warband\nUse: Collect the 3 appearances of the Lightforged Armaments weapon set.\nRequires the completion of the Showdown Slugger achievements for both Val and Naigtal." }
