entries[276371] = { ["name"] = "Lightveil Recall Beacon", ["text"] = "Binds when picked up\nToy\nUse: Recalls you to the current active Umbral Base Camp on Naigtal or Val. Location may vary. (15 Min Cooldown)\n\"Recalls you back to the Umbral Base Camp on Val or Naigtal.\"" }
