entries[276374] = { ["name"] = "Lightveil Rune Reader", ["text"] = "Use: Tap into the to the Lightveil Rune Reader.\n\"Lightforged symbols flicker across the glowing node.\"\nSell Price:" }
entries[276375] = { ["name"] = "Technomancer's Scrying Matrix", ["text"] = "Use: Tap into the Technomancer's Scrying Matrix.\n\"Don't stare too long into the endless expanse of shimmering runic letters.\"\nSell Price:" }
