entries[276405] = { ["name"] = "Elegant Draenite Chopper", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Axe\n1 Damage Speed 2.60\n(0.4 damage per second)\n\"Like a moonlit crescent, as sharp and beautiful as the stars overhead.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[276406] = { ["name"] = "Elegant Talasite Chopper", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Axe\n1 Damage Speed 2.60\n(0.4 damage per second)\n\"The hues of green and blue shimmer as bright as the waters that once flowed around Shattrath.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[276408] = { ["name"] = "Elegant Pyrestone Chopper", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Axe\n1 Damage Speed 2.60\n(0.4 damage per second)\n\"When carved correctly, pyrestone radiates heat from its surface. If its edge won't hurt you, its blaze will.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
