entries[276416] = { ["name"] = "Ceremonial Pyrestone War Maul", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Mace\n1 Damage Speed 2.60\n(0.4 damage per second)\n\"The Pyrestone crown of this mace catches the light with a fiery glow.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
