entries[276549] = { ["name"] = "Topaz Skyfang", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"This elusive wind serpent likes to hide in the forest canopy before stooping down on unsuspecting prey.\"\nDrop:\nThe Coiled Isle Rare Creatures" }
entries[276551] = { ["name"] = "Violet-Backed Skyfang", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequires Renown Rank 19 with Zul'jarra's Forces.\n\n\"The wind serpents of Atal'Utek have venomous tails. You can thank Ula'tek for that.\"\nVendor:\nJan'sari the Watchful\nZone:\nThe Coiled Isle\nCost:\n8000" }
entries[276553] = { ["name"] = "Emerald Skyfang", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Found patrolling the skies of Atal'Utek, maintaining the peace and a full stomach.\"\nAchievement:\nPro Poison Patroller\nCategory:\nMidnight" }
