entries[276801] = { ["name"] = "Venomous Coiler", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"A native of the deadly venom pits within the Vaults of Atal'Utek, this monstrosity poisons the air it slithers past.\"\nAchievement:\nAssault the Vault\nCategory:\nMidnight" }
entries[276802] = { ["name"] = "Indigo Coiled Horror", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequires Renown Rank 17 with Zul'jarra's Forces.\n\n\"Writhes have three distinct temperaments, making them three times as difficult to tame.\"\nVendor:\nJan'sari the Watchful\nZone:\nThe Coiled Isle\nCost:\n6000" }
