entries[278573] = { ["name"] = "Crested Ember Leafmimic", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"This sturdy leafmimic can be found only in the warmest of areas. Its red scales allow it to hide undiscovered in the heated alcoves it prefers.\"\nTrading Post" }
entries[278574] = { ["name"] = "Crested Aqua Leafmimic", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"The aqua leafmimic is a rare sight indeed. Found only in the forests of Ashenvale, its darkened scales allow it to hide among the trees and groves undetected.\"\nTrading Post" }
entries[278575] = { ["name"] = "Crested Verdant Leafmimic", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"Found primarily in areas with dense vegetation, this leafmimic is rarely spotted due to the natural hues of its scales, allowing it to blend in with its surroundings.\"\nTrading Post" }
entries[278576] = { ["name"] = "Crested Violet Leafmimic", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"The violet leafmimic can be found in most dense jungles -- but only if your eyesight is keen. The patterns on their scales allow them to blend in with the vibrant foliage and shadows.\"\nTrading Post" }
